wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn push_section(out: &mut String, heading: &str, items: &[&ItemVerdict]) {
    if items.is_empty() {
        return;
    }
    out.push_str(heading);
    out.push('\n');
    for e in items {
        out.push_str("- [");
        out.push_str(category_label(e.category));
        out.push_str("] ");
        out.push_str(e.title.trim());
        out.push('\n');
        if !e.link.is_empty() {
            out.push_str("  ");
            out.push_str(e.link.trim());
            out.push('\n');
        }
        let summary = e.summary.trim();
        if !summary.is_empty() {
            out.push_str("  ");
            out.push_str(summary);
            out.push('\n');
        }
    }
    out.push('\n');
}

fn render(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(&d.date);
    out.push_str("\n\n");

    let overview = d.overview.trim();
    if !overview.is_empty() {
        out.push_str(overview);
        out.push_str("\n\n");
    }

    let kept: Vec<&ItemVerdict> = d.entries.iter().filter(|e| e.kept).collect();
    let must: Vec<&ItemVerdict> = kept
        .iter()
        .copied()
        .filter(|e| e.importance == Importance::MustRead)
        .collect();
    let worth: Vec<&ItemVerdict> = kept
        .iter()
        .copied()
        .filter(|e| e.importance == Importance::WorthALook)
        .collect();
    let rest: Vec<&ItemVerdict> = kept
        .iter()
        .copied()
        .filter(|e| e.importance == Importance::Skip)
        .collect();

    push_section(&mut out, "Must read:", &must);
    push_section(&mut out, "Worth a look:", &worth);
    push_section(&mut out, "Also noted:", &rest);

    if kept.is_empty() {
        out.push_str("No items made the digest this run.\n\n");
    }

    out.push_str(&format!(
        "{} item(s) considered, {} included.",
        d.considered.len(),
        kept.len()
    ));
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

